"""Checks for Part C. Do not edit this file — your instructor grades with
an original copy, so changing it will not change your grade."""

import pytest

from part_c_functions import (
    average,
    class_report,
    password_strength,
    shopping_total,
    top_student,
)


def test_c1_average():
    assert average([70, 80, 95]) == pytest.approx(81.67), "Round to 2 decimal places"
    assert average([50]) == pytest.approx(50)
    assert average([]) == 0.0, "Empty list → 0.0 (no ZeroDivisionError)"


def test_c2_class_report():
    marks = {"Amina": 74, "Brian": 58, "Chen": 91, "Dee": 39}
    assert class_report(marks) == {"Amina": "A", "Brian": "C", "Chen": "A", "Dee": "E"}
    assert marks == {"Amina": 74, "Brian": 58, "Chen": 91, "Dee": 39}, \
        "Don't change the original dictionary — build a new one"
    assert class_report({}) == {}


def test_c3_top_student():
    assert top_student({"Amina": 74, "Chen": 91, "Dee": 39}) == "Chen"
    assert top_student({"Amina": 80, "Brian": 80}) == "Amina", "On a tie, return the first"
    assert top_student({"Solo": 10}) == "Solo"
    assert top_student({}) is None, "Empty dictionary → None"


def test_c4_shopping_total():
    prices = {"bread": 65, "milk": 60, "eggs": 15}
    assert shopping_total({"bread": 2, "milk": 1}, prices) == pytest.approx(190)
    assert shopping_total({"eggs": 12}, prices) == pytest.approx(180)
    assert shopping_total({"bread": 1, "sugar": 3}, prices) == pytest.approx(65), \
        "Skip items that have no price"
    assert shopping_total({"bread": 2}, prices, discount=10) == pytest.approx(117), \
        "10% off 130 is 117"
    assert shopping_total({}, prices) == pytest.approx(0)


def test_c5_password_strength():
    assert password_strength("Nairobi2026") == "strong"
    assert password_strength("nairobi2026") == "medium", "Long + digit, no uppercase"
    assert password_strength("Short1") == "medium", "Digit + uppercase, too short"
    assert password_strength("password") == "weak", "Only the length rule"
    assert password_strength("abc") == "weak", "No rules met"
